// DIJKSTRA'S ALGORITHM
// O((V+E) log V) time, O(V+E) space

// Simple min-heap simulation using sorted array (interview clarity)
// Production: use a proper MinHeap from Module 9
function dijkstra(graph, source, n) {
    const dist = new Array(n).fill(Infinity);
    dist[source] = 0;

    // Min-heap: [distance, vertex] pairs
    // Using array sorted by distance (O(log n) operations with proper heap)
    const heap = [[0, source]]; // [dist, vertex]

    while (heap.length) {
        // Extract minimum distance vertex
        heap.sort((a, b) => a[0] - b[0]); // O(n log n) naive; O(log n) with proper heap
        const [d, u] = heap.shift();

        if (d > dist[u]) continue; // LAZY DELETION: stale entry, skip

        for (const [v, w] of (graph[u] || [])) {
            const newDist = dist[u] + w;
            if (newDist < dist[v]) {
                dist[v] = newDist;
                heap.push([newDist, v]); // add updated entry (lazy: don't remove old)
            }
        }
    }
    return dist; // dist[v] = shortest distance from source to v
}

// TEST: network from Lesson 1
