    [[0,4],[3,1]],  // 1: connects to 0, 3(cost 1)
    [[0,1],[1,2],[3,5]], // 2: connects to 0, 1(cost 2), 3(cost 5)
    [[1,1],[2,5],[4,3]], // 3: connects to 1, 2, 4(cost 3)
    [[3,3]]         // 4: connects to 3
];
const distances = dijkstra(adj, 0, 5);
console.log(distances); // [0, 3, 1, 4, 7]
