function dijkstraImpl(graph, source, n) {
  const dist = new Array(n).fill(Infinity);
  dist[source] = 0;
  const heap = [[0, source]];
  while (heap.length) {
    heap.sort((a,b) => a[0]-b[0]);
    const [d, u] = heap.shift();
    if (d > dist[u]) continue;
    for (const [v, w] of (graph[u] || [])) {
      const nd = dist[u] + w;
      if (nd < dist[v]) { dist[v] = nd; heap.push([nd, v]); }
    }
  }
  return dist;
}

