// BELLMAN-FORD ALGORITHM
// O(V*E) time, O(V) space
function bellmanFord(n, edges, source) {
    // edges: [[u, v, w], ...] directed weighted edges
    const dist = new Array(n).fill(Infinity);
    dist[source] = 0;

    // V-1 rounds of relaxation
    for (let round = 0; round < n - 1; round++) {
        let updated = false;
        for (const [u, v, w] of edges) {
            if (dist[u] !== Infinity && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                updated = true;
            }
        }
        if (!updated) break; // EARLY TERMINATION: no change, done
    }

    // V-th round: detect negative cycle
    for (const [u, v, w] of edges) {
        if (dist[u] !== Infinity && dist[u] + w < dist[v]) {
            return null; // NEGATIVE CYCLE DETECTED
        }
    }

    return dist;
}

// TEST: graph with negative edge
const edges1 = [[0,1,4],[0,2,5],[1,2,-3],[2,3,2]];
console.log(bellmanFord(4, edges1, 0));
// [0, 4, 1, 3]
// 0->1: 4
// 0->1->2: 4+(-3)=1 (better than 0->2: 5)
// 0->1->2->3: 1+2=3

// TEST: negative cycle detection
const edgesNegCycle = [[0,1,1],[1,2,1],[2,0,-4],[0,3,5]];
console.log(bellmanFord(4, edgesNegCycle, 0));
// null: 0->1->2->0 has weight 1+1+(-4) = -2 (negative cycle)

// PROOF: why V-1 rounds are sufficient
// Claim: after k rounds, dist[v] is the shortest path using at most k edges
// Base: round 0, dist[source]=0 (0 edges to source)
// Inductive step: if after k rounds all k-edge paths are correct,
//   round k+1 relaxes all edges, extending k-edge paths to (k+1)-edge paths
// Since shortest paths without negative cycles use at most V-1 edges:
// after V-1 rounds, all shortest paths are correct.

// BELLMAN-FORD vs DIJKSTRA:
// Dijkstra: O((V+E) log V), non-negative weights only, greedy
// Bellman-Ford: O(V*E), handles negative weights, detects negative cycles

