// NETWORK DELAY TIME (#743)
// O((V+E) log V) time using Dijkstra
function networkDelayTime(times, n, k) {
    // Build adjacency list (1-indexed nodes)
    const adj = Array.from({length: n+1}, () => []);
    for (const [u, v, w] of times) {
        adj[u].push([v, w]);
    }

    // Dijkstra from source k
    const dist = new Array(n+1).fill(Infinity);
    dist[k] = 0;
    const heap = [[0, k]]; // [distance, node]

    while (heap.length) {
        heap.sort((a,b) => a[0]-b[0]);
        const [d, u] = heap.shift();
        if (d > dist[u]) continue; // lazy deletion

        for (const [v, w] of adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap.push([dist[v], v]);
            }
        }
    }

    // Find maximum distance among all nodes 1..n
    let maxDist = 0;
    for (let node = 1; node <= n; node++) {
        if (dist[node] === Infinity) return -1; // unreachable node
        maxDist = Math.max(maxDist, dist[node]);
    }
    return maxDist;
}

console.log(networkDelayTime([[2,1,1],[2,3,1],[3,4,1]], 4, 2)); // 2
// Signal from 2: 2->1 (1ms), 2->3 (1ms), 3->4 (2ms)
// All nodes reached. Maximum distance = 2 (node 4 takes 2ms).

console.log(networkDelayTime([[1,2,1]], 2, 2)); // -1
// Source is 2, edge is 1->2 (wrong direction). Node 1 unreachable from 2.

// TERMINATION OPTIMISATION:
// If only the maximum distance to any single node is needed:
// Can terminate Dijkstra when all n nodes have been extracted
// (not just when heap is empty, to avoid processing unreachable nodes)

// ALTERNATIVE: detect early when ALL nodes are extracted
function networkDelayTime_opt(times, n, k) {
    const adj = Array.from({length: n+1}, () => []);
    for (const [u, v, w] of times) adj[u].push([v, w]);

    const dist = new Array(n+1).fill(Infinity);
    dist[k] = 0;
    const heap = [[0, k]];
    let processed = 0;

    while (heap.length && processed < n) {
        heap.sort((a,b) => a[0]-b[0]);
        const [d, u] = heap.shift();
        if (d > dist[u]) continue;
        processed++;
        for (const [v, w] of adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap.push([dist[v], v]);
            }
        }
    }

    let ans = 0;
    for (let i = 1; i <= n; i++) {
        if (dist[i] === Infinity) return -1;
        ans = Math.max(ans, dist[i]);
    }
    return ans;
}

