// CHEAPEST FLIGHTS WITHIN K STOPS (#787)
// O(K*E) time, O(V) space
function findCheapestPrice(n, flights, src, dst, k) {
    // dist[v] = min cost to reach v using at most current_round edges
    const dist = new Array(n).fill(Infinity);
    dist[src] = 0;

    // K+1 rounds: k stops = k+1 edges
    for (let round = 0; round <= k; round++) {
        // CRITICAL: copy dist before this round's updates
        // Ensures each round only extends paths by ONE edge
        const prevDist = [...dist];

        for (const [u, v, price] of flights) {
            // Use prevDist[u] (last round's distance) not dist[u] (this round)
            if (prevDist[u] !== Infinity && prevDist[u] + price < dist[v]) {
                dist[v] = prevDist[u] + price;
            }
        }
    }

    return dist[dst] === Infinity ? -1 : dist[dst];
}

console.log(findCheapestPrice(4, [[0,1,100],[1,2,100],[2,0,100],[1,3,600],[2,3,200]], 0, 3, 1));
// k=1 stop = 2 edges maximum
