// 0->1->2->3: cost 300 but requires 3 edges (2 stops)
// Answer: 700

console.log(findCheapestPrice(3, [[0,1,100],[1,2,100],[0,2,500]], 0, 2, 1));
// k=1: 0->2 direct: 500. 0->1->2: 200 but 2 edges (1 stop OK). Answer: 200

