function dijkstraTemplate(graph, source, n) {
    const dist = new Array(n).fill(Infinity);
    dist[source] = 0;
    const heap = [[0, source]];
    while (heap.length) {
        heap.sort((a,b) => a[0]-b[0]); // use proper MinHeap in production
        const [d, u] = heap.shift();
        if (d > dist[u]) continue; // lazy deletion
        for (const [v, w] of graph[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap.push([dist[v], v]);
            }
        }
    }
    return dist;
}

// TEMPLATE 2: Bellman-Ford (negative weights or k-hop)
function bellmanFordTemplate(edges, n, source, maxRounds) {
    const dist = new Array(n).fill(Infinity);
    dist[source] = 0;
    for (let r = 0; r < maxRounds; r++) {
        const prev = [...dist]; // ALWAYS copy for k-hop; optional for regular BF
        let updated = false;
        for (const [u, v, w] of edges) {
            if (prev[u] !== Infinity && prev[u] + w < dist[v]) {
                dist[v] = prev[u] + w;
                updated = true;
            }
        }
        if (!updated) break;
    }
    return dist;
}

